def shift(text, key):
    result = ""
    for ch in text:
        if ch.isalpha():
            result = result + chr((ord(ch) - 65 + key) % 26 + 65)
        else:
            result = result + ch
    return result

secret = shift("MEET AT FAJR", 3)
print(secret)
print(shift(secret, -3))

def write_report(records, filename):
    f = open(filename, 'w')
    for name, sessions, attended in records:
        p = attended / sessions * 100
        f.write(name + ',' + str(round(p, 1)) + '\n')
    f.close()

def count_overdue(loans):
    count = 0
    for loan in loans:
        if loan[2] < 0:
            print('Invalid:', loan)
        elif loan[2] > 14:
            count = count + 1
    return count

